{
  "schemaVersion": "0.2",
  "slug": "data-grid",
  "name": "DataGrid",
  "family": "D",
  "status": "experimental",
  "purpose": "Virtualized data grid rendering tens of thousands of rows in a windowed viewport with a replaceable virtualization engine.",
  "scenarios": [
    "Browse 10k log entries",
    "Audit a large transaction table",
    "Scroll a telemetry feed"
  ],
  "props": {
    "columns": {
      "type": "string",
      "required": true,
      "description": "Array of { key, header, width?, render? } column definitions."
    },
    "rows": {
      "type": "string",
      "required": true,
      "description": "Array of row data objects; tested at 10k entries."
    },
    "rowHeight": {
      "type": "number",
      "required": false,
      "description": "Fixed row height in px.",
      "default": 36
    },
    "height": {
      "type": "number",
      "required": false,
      "description": "Viewport height in px.",
      "default": 420
    },
    "overscan": {
      "type": "number",
      "required": false,
      "description": "Extra rows rendered beyond the viewport.",
      "default": 6
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the grid."
    },
    "getRowId": {
      "type": "string",
      "required": false,
      "description": "Row id accessor for stable keys."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Windowed rows rendered."
    },
    {
      "name": "empty",
      "description": "No rows provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "app-shell",
      "card"
    ],
    "allowedChildren": [
      "tag",
      "badge",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not render all rows at once; keep virtualization on.",
    "Do not use variable row heights with the fixed-height engine."
  ],
  "a11y": {
    "role": "grid",
    "keyboard": [
      "Page keys move the viewport",
      "Tab moves through cell actions"
    ],
    "focus": "Row cells expose aria-rowindex against the full row count.",
    "labeling": "aria-label names the grid; aria-rowcount reflects total rows.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Viewport height stays fixed; columns scroll horizontally on compact.",
    "breakpoints": {
      "compact": "Horizontal column scroll.",
      "medium": "Fit container.",
      "large": "Fit container."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "data-grid",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "inspect-tabular-data"
    ]
  }
}

import { useState } from 'react'
import type { ReactNode } from 'react'
import './styles.css'

export interface DataGridColumn<T = unknown> {
  key: string
  header: ReactNode
  width?: number
  render?: (row: T) => ReactNode
}

export interface DataGridProps<T = unknown> {
  columns: DataGridColumn<T>[]
  rows: T[]
  rowHeight?: number
  height?: number
  width?: number
  overscan?: number
  label: string
  emptyLabel?: string
  getRowId?: (row: T, index: number) => string
  className?: string
}

export interface VirtualWindow {
  start: number
  end: number
}

/**
 * @complexity time O(1) | space O(1) — window edges from scroll offset only
 * @guarantees rendered row/column count stays O(viewport) regardless of data size
 */
export function computeWindow(offset: number, viewport: number, count: number, size: number, overscan: number): VirtualWindow {
  const start = Math.max(0, Math.floor(offset / size) - overscan)
  const end = Math.min(count, Math.ceil((offset + viewport) / size) + overscan)
  return { start, end }
}

const DEFAULT_COLUMN_WIDTH = 160

export function DataGrid<T>({
  columns,
  rows,
  rowHeight = 36,
  height = 420,
  width = 960,
  overscan = 6,
  label,
  emptyLabel = 'No data',
  getRowId,
  className,
}: DataGridProps<T>) {
  const [scrollTop, setScrollTop] = useState(0)
  const [scrollLeft, setScrollLeft] = useState(0)
  const classes = ['cu-data-grid', className].filter(Boolean).join(' ')

  const rowWindow = computeWindow(scrollTop, height, rows.length, rowHeight, overscan)
  const columnWidths = columns.map((column) => column.width ?? DEFAULT_COLUMN_WIDTH)
  const columnOffsets: number[] = []
  let running = 0
  for (const columnWidth of columnWidths) {
    columnOffsets.push(running)
    running += columnWidth
  }
  const totalWidth = running
  const columnWindow = computeWindow(scrollLeft, width, columns.length, DEFAULT_COLUMN_WIDTH, 2)

  return (
    <div className={classes} data-ai-role="data-grid" data-ai-intent="inspect-tabular-data" data-ai-state={rows.length === 0 ? 'empty' : 'default'}>
      <div
        className="cu-data-grid__viewport"
        role="grid"
        aria-label={label}
        aria-rowcount={rows.length + 1}
        aria-colcount={columns.length}
        style={{ blockSize: height, inlineSize: '100%', maxInlineSize: width }}
        onScroll={(event) => {
          setScrollTop(event.currentTarget.scrollTop)
          setScrollLeft(event.currentTarget.scrollLeft)
        }}
      >
        {rows.length === 0 ? (
          <p className="cu-data-grid__empty">{emptyLabel}</p>
        ) : (
          <div
            className="cu-data-grid__canvas"
            style={{ blockSize: (rows.length + 1) * rowHeight, inlineSize: totalWidth }}
          >
            <div
              className="cu-data-grid__row cu-data-grid__row--head"
              role="row"
              aria-rowindex={1}
              style={{ transform: `translateY(${scrollTop}px)` }}
            >
              {columns.slice(columnWindow.start, columnWindow.end).map((column, offsetIndex) => {
                const columnIndex = columnWindow.start + offsetIndex
                return (
                  <div
                    key={column.key}
                    className="cu-data-grid__cell cu-data-grid__cell--head"
                    role="columnheader"
                    aria-colindex={columnIndex + 1}
                    style={{ insetInlineStart: columnOffsets[columnIndex], inlineSize: columnWidths[columnIndex] }}
                  >
                    {column.header}
                  </div>
                )
              })}
            </div>
            {rows.slice(rowWindow.start, rowWindow.end).map((row, offsetIndex) => {
              const rowIndex = rowWindow.start + offsetIndex
              return (
                <div
                  key={getRowId ? getRowId(row, rowIndex) : rowIndex}
                  className="cu-data-grid__row"
                  role="row"
                  aria-rowindex={rowIndex + 2}
                  style={{ transform: `translateY(${(rowIndex + 1) * rowHeight}px)`, blockSize: rowHeight }}
                >
                  {columns.slice(columnWindow.start, columnWindow.end).map((column, offset) => {
                    const columnIndex = columnWindow.start + offset
                    return (
                      <div
                        key={column.key}
                        className="cu-data-grid__cell"
                        role="gridcell"
                        aria-colindex={columnIndex + 1}
                        style={{ insetInlineStart: columnOffsets[columnIndex], inlineSize: columnWidths[columnIndex] }}
                      >
                        {column.render ? column.render(row) : String((row as Record<string, unknown>)[column.key] ?? '')}
                      </div>
                    )
                  })}
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

.cu-data-grid {
  display: block;
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  overflow: hidden;
}

.cu-data-grid__viewport {
  position: relative;
  overflow: auto;
}

.cu-data-grid__canvas {
  position: relative;
}

.cu-data-grid__row {
  position: absolute;
  inset-inline: 0;
  display: block;
}

.cu-data-grid__row--head {
  z-index: 1;
  font-weight: 600;
  border-block-end: 1px solid var(--cu-color-border-default);
  background: var(--cu-color-background-default);
}

.cu-data-grid__cell {
  position: absolute;
  inset-block: 0;
  display: flex;
  align-items: center;
  padding-inline: var(--cu-space-2);
  overflow: hidden;
  white-space: nowrap;
  border-block-end: 1px solid color-mix(in srgb, var(--cu-color-border-default) 50%, transparent);
}

.cu-data-grid__empty {
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}
